import products from './products.json' with {type:'json'};

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name (case-insensitive).',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query to match against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results (1-10).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error('Unknown tool: ' + name);
  }

  args = args || {};

  // Validate additionalProperties
  const knownKeys = new Set(['query', 'limit']);
  for (const key of Object.keys(args)) {
    if (!knownKeys.has(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('query is required and must be a string');
  }

  if (limit !== undefined) {
    if (!Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
  }

  const q = query.toLowerCase();
  let results = products.filter(p => p.name.toLowerCase().includes(q));

  const effectiveLimit = limit !== undefined ? limit : results.length;
  results = results.slice(0, effectiveLimit);

  const text = results.map(p => `${p.id}: ${p.name}`).join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}
